from itertools import combinations

# Build T(7): triangular graph
subsets = list(combinations(range(7), 2))

edges = []
for i, s1 in enumerate(subsets):
    for j, s2 in enumerate(subsets):
        if i < j and set(s1) & set(s2):
            edges.append((i, j))

# Build adjacency list
adj = [[] for _ in range(21)]
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

# Let's verify vertex connectivity more carefully
# For vertex-disjoint paths, use a simpler approach:
# Repeatedly find paths and remove internal vertices

def find_path(adj, source, sink, removed):
    """Find a path from source to sink avoiding removed vertices"""
    from collections import deque
    if source in removed or sink in removed:
        return None
    queue = deque([source])
    parent = {source: None}
    while queue:
        u = queue.popleft()
        if u == sink:
            path = []
            cur = sink
            while cur is not None:
                path.append(cur)
                cur = parent[cur]
            return path[::-1]
        for v in adj[u]:
            if v not in removed and v not in parent:
                parent[v] = u
                queue.append(v)
    return None

def vertex_connectivity_pair(adj, source, sink):
    """Number of internally vertex-disjoint paths from source to sink"""
    if source == sink:
        return float('inf')
    # Check if directly connected
    if sink in adj[source]:
        # Direct edge counts as one path
        count = 1
        removed = {source, sink}
    else:
        count = 0
        removed = {source, sink}

    while True:
        path = find_path(adj, source, sink, removed)
        if path is None:
            break
        count += 1
        # Remove internal vertices
        for v in path[1:-1]:
            removed.add(v)

    return count

# Test a few pairs
test_pairs = [(0, 1), (0, 20), (5, 10), (3, 15), (2, 7)]
for u, v in test_pairs:
    conn = vertex_connectivity_pair(adj, u, v)
    print(f"Connectivity between {u} ({subsets[u]}) and {v} ({subsets[v]}): {conn}")

# Find minimum connectivity over all pairs
min_conn = float('inf')
worst_pairs = []
for u in range(21):
    for v in range(u+1, 21):
        conn = vertex_connectivity_pair(adj, u, v)
        if conn < min_conn:
            min_conn = conn
            worst_pairs = [(u, v)]
        elif conn == min_conn:
            worst_pairs.append((u, v))

print(f"\nMinimum vertex connectivity: {min_conn}")
print(f"Number of worst pairs: {len(worst_pairs)}")
print(f"First few worst pairs: {worst_pairs[:5]}")
for u, v in worst_pairs[:5]:
    print(f"  {u} ({subsets[u]}) - {v} ({subsets[v]})")

