from itertools import combinations
from collections import deque

# Build T(7): triangular graph
subsets = list(combinations(range(7), 2))

edges = []
for i, s1 in enumerate(subsets):
    for j, s2 in enumerate(subsets):
        if i < j and set(s1) & set(s2):
            edges.append((i, j))

# Build adjacency list
adj = [[] for _ in range(21)]
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

def max_vertex_disjoint_paths(adj, source, sink, n):
    """Find max number of internally vertex-disjoint paths from source to sink"""
    if source == sink:
        return float('inf')

    # Node splitting for vertex capacities
    # For each vertex v, create v_in = 2*v and v_out = 2*v + 1
    # Edge v_in -> v_out has capacity 1 (vertex capacity)
    # For source and sink, capacity is infinity (or n)

    N = 2 * n

    # Build adjacency list for flow network with capacities
    # graph[u] = list of (v, capacity, reverse_edge_index)
    graph = [[] for _ in range(N)]

    def add_edge(u, v, cap):
        graph[u].append([v, cap, len(graph[v])])
        graph[v].append([u, 0, len(graph[u]) - 1])

    # Add vertex capacity edges
    for i in range(n):
        if i == source or i == sink:
            add_edge(2*i, 2*i+1, n)  # Large capacity
        else:
            add_edge(2*i, 2*i+1, 1)  # Unit capacity

    # Add edges between vertices
    for u in range(n):
        for v in adj[u]:
            # u_out -> v_in
            add_edge(2*u+1, 2*v, n)

    # Dinic's algorithm
    def bfs():
        level = [-1] * N
        level[2*source+1] = 0  # Start from source_out
        queue = deque([2*source+1])
        while queue:
            u = queue.popleft()
            for v, cap, rev in graph[u]:
                if cap > 0 and level[v] < 0:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level

    def dfs(u, flow, level, ptr):
        if u == 2*sink:  # Reached sink_in
            return flow
        while ptr[u] < len(graph[u]):
            v, cap, rev = graph[u][ptr[u]]
            if cap > 0 and level[v] == level[u] + 1:
                f = dfs(v, min(flow, cap), level, ptr)
                if f > 0:
                    graph[u][ptr[u]][1] -= f
                    graph[v][rev][1] += f
                    return f
            ptr[u] += 1
        return 0

    max_flow = 0
    while True:
        level = bfs()
        if level[2*sink] < 0:
            break
        ptr = [0] * N
        while True:
            f = dfs(2*source+1, n, level, ptr)
            if f == 0:
                break
            max_flow += f

    return max_flow

# Test a few pairs
test_pairs = [(0, 1), (0, 20), (5, 10), (3, 15), (2, 7), (0, 11)]
for u, v in test_pairs:
    conn = max_vertex_disjoint_paths(adj, u, v, 21)
    print(f"Connectivity between {u} ({subsets[u]}) and {v} ({subsets[v]}): {conn}")

# Find minimum connectivity over all pairs (sample first)
min_conn = float('inf')
worst_pair = None
for u in range(21):
    for v in range(u+1, 21):
        conn = max_vertex_disjoint_paths(adj, u, v, 21)
        if conn < min_conn:
            min_conn = conn
            worst_pair = (u, v)

